#!/bin/bash
# Print the three most frequent IP addresses in access.log,
# most frequent first; break ties by first appearance in the log.
awk '
{
    ip = $1
    if (!(ip in count)) {
        count[ip] = 0
        order[++n] = ip
    }
    count[ip]++
}
END {
    for (i = 1; i <= 3; i++) {
        best = ""
        for (j = 1; j <= n; j++) {
            if (!(order[j] in picked)) {
                if (best == "" || count[order[j]] > count[best])
                    best = order[j]
            }
        }
        picked[best] = 1
        print best
    }
}
' access.log
